# -*- coding: utf-8 -*-
"""ТИПО — исправленная пустая коробка по оригинальному SVG.

Blender 4.x: Text Editor → Open → Run Script.
Графика и векторные контуры уже встроены. Внешние PNG, SVG и сеть не нужны.
Коробка 67 × 67 × 27 мм. Карт внутри нет. Существующие сцены не удаляются.
"""
import base64
import io
import json
import math
import os
import tempfile
import zipfile
from datetime import datetime
from pathlib import Path

import bpy
import numpy as np
from mathutils import Vector
from mathutils.geometry import tessellate_polygon

# ----------------------- НАСТРОЙКИ -----------------------
BOX_MM = 67.0
DEPTH_MM = 27.0
BOARD_MM = 0.35  # Предположение: физическая толщина картона пока не указана.
MM = 0.001
PAPER_HEX = '#FFFCF4'
RENDER_NOW = os.environ.get('TIPO_RENDER', '1') == '1'
RENDER_SIZE = int(os.environ.get('TIPO_RENDER_SIZE', '1400'))
SAMPLES = int(os.environ.get('TIPO_SAMPLES', '128'))
OUTPUT_DIR = Path(os.environ.get('TIPO_OUTPUT_DIR', str(Path.home() / 'Downloads' / 'TIPO_3D')))
PANEL_NAMES = ('front', 'left', 'right', 'back', 'bottom', 'top', 'tuck')

def srgb(hex_color):
    return np.array([int(hex_color[i:i + 2], 16) / 255 for i in (1, 3, 5)])


def linear_color(hex_color):
    values = srgb(hex_color)
    linear = np.where(values <= 0.04045, values / 12.92,
                      ((values + 0.055) / 1.055) ** 2.4)
    return (*map(float, linear), 1.0)


def set_input(node, names, value):
    for name in names:
        if name in node.inputs:
            node.inputs[name].default_value = value
            return


def paper_material(name, image=None, color=PAPER_HEX, gloss=True, edge=False):
    material = bpy.data.materials.new(name)
    material.use_nodes = True
    material.diffuse_color = linear_color(color)
    nodes, links = material.node_tree.nodes, material.node_tree.links
    nodes.clear()
    output = nodes.new('ShaderNodeOutputMaterial')
    output.location = (650, 60)
    shader = nodes.new('ShaderNodeBsdfPrincipled')
    shader.location = (340, 60)
    shader.inputs['Base Color'].default_value = linear_color(color)
    shader.inputs['Roughness'].default_value = 0.28 if gloss else 0.62
    shader.inputs['IOR'].default_value = 1.46
    set_input(shader, ('Coat Weight', 'Clearcoat'), 0.42 if gloss else 0.0)
    set_input(shader, ('Coat Roughness', 'Clearcoat Roughness'), 0.18)
    links.new(shader.outputs['BSDF'], output.inputs['Surface'])
    if image:
        texture = nodes.new('ShaderNodeTexImage')
        texture.name = 'Авторский PNG — sRGB, без перекрашивания'
        texture.label = texture.name
        texture.image = image
        texture.interpolation = 'Linear'
        texture.extension = 'EXTEND'
        texture.location = (-430, 220)
        uv_node = nodes.new('ShaderNodeUVMap')
        uv_node.uv_map = 'Авторская развёртка'
        uv_node.location = (-650, 220)
        links.new(uv_node.outputs['UV'], texture.inputs['Vector'])
        links.new(texture.outputs['Color'], shader.inputs['Base Color'])
    geometry = nodes.new('ShaderNodeNewGeometry')
    geometry.location = (-850, -150)
    noise = nodes.new('ShaderNodeTexNoise')
    noise.location = (-600, -150)
    noise.inputs['Scale'].default_value = 14000.0 if edge else 10000.0
    noise.inputs['Detail'].default_value = 2.0
    noise.inputs['Roughness'].default_value = 0.65
    links.new(geometry.outputs['Position'], noise.inputs['Vector'])
    bump = nodes.new('ShaderNodeBump')
    bump.location = (40, -120)
    bump.inputs['Strength'].default_value = 0.14 if edge else 0.075
    bump.inputs['Distance'].default_value = 0.000012 if edge else 0.000006
    links.new(noise.outputs['Fac'], bump.inputs['Height'])
    links.new(bump.outputs['Normal'], shader.inputs['Normal'])
    # Ламинат остаётся гладким: микрорельеф бумаги под глянцевым слоем.
    ramp = nodes.new('ShaderNodeMapRange')
    ramp.location = (-150, -330)
    ramp.inputs['From Min'].default_value = 0.0
    ramp.inputs['From Max'].default_value = 1.0
    ramp.inputs['To Min'].default_value = 0.24 if gloss else 0.55
    ramp.inputs['To Max'].default_value = 0.30 if gloss else 0.72
    links.new(noise.outputs['Fac'], ramp.inputs['Value'])
    links.new(ramp.outputs['Result'], shader.inputs['Roughness'])
    return material


def mesh_object(name, vertices, faces, collection):
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(vertices, [], faces)
    mesh.validate()
    mesh.update()
    obj = bpy.data.objects.new(name, mesh)
    collection.objects.link(obj)
    return obj


def cuboid(name, lo, hi, collection):
    x0, y0, z0 = lo
    x1, y1, z1 = hi
    vertices = [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0),
                (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)]
    faces = [(3, 2, 1, 0), (0, 1, 5, 4), (1, 2, 6, 5),
             (2, 3, 7, 6), (3, 0, 4, 7), (4, 5, 6, 7)]
    return mesh_object(name, vertices, faces, collection)


def prism(name, profile, z0, z1, collection):
    profile = list(profile)
    area = sum(profile[i][0] * profile[(i + 1) % len(profile)][1]
               - profile[(i + 1) % len(profile)][0] * profile[i][1]
               for i in range(len(profile)))
    if area < 0:
        profile.reverse()
    n = len(profile)
    vectors = [Vector((x, y, 0.0)) for x, y in profile]
    triangles = tessellate_polygon([vectors])
    index = {(v.x, v.y): i for i, v in enumerate(vectors)}
    faces = []
    for triangle in triangles:
        # Blender возвращает индексы; поддерживаем и варианты API с Vector.
        ids = tuple(index[(v.x, v.y)] if hasattr(v, 'x') else int(v)
                    for v in triangle)
        faces.extend([tuple(reversed(ids)), tuple(i + n for i in ids)])
    faces += [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)]
    vertices = [(x, y, z) for z in (z0, z1) for x, y in profile]
    return mesh_object(name, vertices, faces, collection)


def apply_cut(obj, cutter):
    modifier = obj.modifiers.new('Настоящий сквозной вырез', 'BOOLEAN')
    modifier.operation = 'DIFFERENCE'
    modifier.solver = 'EXACT'
    modifier.object = cutter
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    bpy.ops.object.modifier_apply(modifier=modifier.name)
    bpy.data.objects.remove(cutter, do_unlink=True)
    obj.select_set(False)


def finish_surface(obj, printed_material, paper, outward, uv_function, bevel_mm=0.045):
    obj.data.materials.append(printed_material)
    obj.data.materials.append(paper)
    obj.data.update()
    uv = obj.data.uv_layers.new(name='Авторская развёртка')
    direction = Vector(outward)
    for polygon in obj.data.polygons:
        polygon.material_index = 0 if polygon.normal.dot(direction) > 0.9 else 1
        for loop_index in polygon.loop_indices:
            co = obj.data.vertices[obj.data.loops[loop_index].vertex_index].co
            uv.data[loop_index].uv = uv_function(co)
    bevel = obj.modifiers.new('Мягкий край бумаги', 'BEVEL')
    bevel.width = bevel_mm * MM
    bevel.segments = 3
    bevel.limit_method = 'ANGLE'
    bevel.angle_limit = math.radians(32)
    bevel.material = 1
    bevel.use_clamp_overlap = True
    return obj


def point_at(obj, target):
    obj.rotation_euler = (Vector(target) - obj.location).to_track_quat('-Z', 'Y').to_euler()


def area_light(collection, name, location, target, energy, size, size_y=None):
    data = bpy.data.lights.new(name, 'AREA')
    data.energy = energy
    data.shape = 'RECTANGLE' if size_y else 'DISK'
    data.size = size
    if size_y:
        data.size_y = size_y
    obj = bpy.data.objects.new(name, data)
    collection.objects.link(obj)
    obj.location = location
    point_at(obj, target)
    return obj

def load_embedded_artwork():
    data = base64.b64decode(ARTWORK_ZIP)
    images = {}
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        if archive.testzip() is not None:
            raise RuntimeError('Повреждён встроенный архив рисунка. Скачайте скрипт целиком.')
        geometry = json.loads(archive.read('geometry.json'))
        with tempfile.TemporaryDirectory(prefix='TIPO_artwork_') as temp:
            for name in PANEL_NAMES:
                path = Path(temp) / (name + '.png')
                path.write_bytes(archive.read(name + '.png'))
                image = bpy.data.images.load(str(path), check_existing=False)
                image.name = 'TIPO SVG • авторская печать • ' + name
                image.colorspace_settings.name = 'sRGB'
                image.alpha_mode = 'STRAIGHT'
                image.pack()
                image.filepath = '//TIPO_embedded/' + name + '.png'
                image.use_fake_user = True
                images[name] = image
    return geometry, images


def create_upright_view(source):
    """Дополнительная предметная сцена: та же коробка стоит вертикально."""
    from mathutils import Matrix
    view = source.copy()
    view.name = 'TIPO_Верх_стоя'
    view.use_fake_user = True
    for child in list(view.collection.children):
        view.collection.children.unlink(child)
    transform = (Matrix.Translation((0, 0, BOX_MM * MM / 2))
                 @ Matrix.Rotation(math.pi / 2, 4, 'X'))
    main_camera = None
    for original_collection in source.collection.children:
        collection = bpy.data.collections.new(original_collection.name + ' • стоя')
        view.collection.children.link(collection)
        for original in original_collection.objects:
            obj = original.copy()
            if original.type == 'CAMERA':
                obj.data = original.data.copy()
            collection.objects.link(obj)
            if original_collection.name.startswith('01'):
                obj.matrix_world = transform @ original.matrix_world
            if original == source.camera:
                main_camera = obj
    assert main_camera is not None
    main_camera.name = 'Камера • крышка с логотипом • стоящая коробка'
    main_camera.location = (0.095, -0.16, 0.145)
    point_at(main_camera, (0, -DEPTH_MM * MM / 2, BOX_MM * MM / 2))
    main_camera.data.ortho_scale = 0.115
    view.camera = main_camera
    view['Ракурс'] = 'Коробка поставлена вертикально; текстуры и геометрия совпадают.'
    return view


def build():
    if bpy.app.version < (4, 0, 0):
        raise RuntimeError('Используйте Blender 4.0 или новее.')
    print('TIPO SVG: загружаю встроенную авторскую графику…', flush=True)
    geometry, images = load_embedded_artwork()
    scene = bpy.data.scenes.new('TIPO_Empty_SVG')
    scene['TIPO_generator'] = '3.0 • цельный верхний логотип • синий клапан'
    scene['Источник'] = 'коробка без лого.svg — оригинал пользователя'
    scene['Размер коробки, мм'] = '67 × 67 × 27'
    scene['Карт внутри'] = 0
    scene['Контур окна'] = 'Из векторного path SVG, точность аппроксимации менее 0.01 мм.'
    scene['Толщина картона, мм'] = BOARD_MM
    if bpy.context.window:
        bpy.context.window.scene = scene
    scene.unit_settings.system = 'METRIC'
    scene.unit_settings.length_unit = 'MILLIMETERS'
    scene.unit_settings.scale_length = 1.0
    packaging = bpy.data.collections.new('01 • Пустая коробка • оригинальный SVG')
    studio = bpy.data.collections.new('02 • Свет, камера, фон')
    scene.collection.children.link(packaging)
    scene.collection.children.link(studio)
    paper = paper_material('TIPO SVG • внутренняя бумага и торец', gloss=False, edge=True)
    materials = {key: paper_material('TIPO SVG • глянцевая печать • ' + key, image=images[key])
                 for key in PANEL_NAMES}
    half, depth, t = BOX_MM * MM / 2, DEPTH_MM * MM, BOARD_MM * MM
    span = half * 2
    scale = BOX_MM / 67.0
    outer = [(x * scale, y * scale) for x, y in geometry['outer']]
    window = [(x * scale, y * scale) for x, y in geometry['window']]
    front = prism('Лицевая панель • рисунок + сквозное фигурное окно',
                  outer, depth - t, depth, packaging)
    cutter = prism('Векторный контур окна', window, depth - t - 0.002, depth + 0.002, packaging)
    apply_cut(front, cutter)
    finish_surface(front, materials['front'], paper, (0, 0, 1),
                   lambda p: ((p.x + half) / span, (p.y + half) / span))
    front['Графика'] = 'Жёлтые цветы, розовые завитки, зелёная графика, синие точки — из SVG.'
    front['Геометрия'] = 'Фигурное окно и верхняя выемка действительно прорезаны.'
    printed_area = sum(p.area for p in front.data.polygons if p.material_index == 0)
    if printed_area < span * span * 0.4:
        raise RuntimeError('Лицевая текстура не назначена поверхности; сборка остановлена.')

    definitions = [
        ('Левая боковина', 'left', (-half, -half, t), (-half + t, half, depth - t),
         (-1, 0, 0), lambda p: (p.z / depth, (p.y + half) / span)),
        ('Правая боковина', 'right', (half - t, -half, t), (half, half, depth - t),
         (1, 0, 0), lambda p: (1 - p.z / depth, (p.y + half) / span)),
        ('Задняя панель', 'back', (-half, -half, 0), (half, half, t),
         (0, 0, -1), lambda p: ((half - p.x) / span, (p.y + half) / span)),
        ('Нижний сгиб', 'bottom', (-half + t, -half, t), (half - t, -half + t, depth - t),
         (0, -1, 0), lambda p: ((p.x + half) / span, p.z / depth)),
        ('Верхний закрывающий клапан', 'top', (-half + t, half - t, t),
         (half - t, half, depth - t), (0, 1, 0),
         lambda p: ((half - p.x) / span, p.z / depth)),
    ]
    for name, key, lo, hi, normal, uv in definitions:
        finish_surface(cuboid(name, lo, hi, packaging), materials[key], paper, normal, uv)
    tuck_depth = 180.0 / 791.0 * BOX_MM * MM
    tuck_z = depth - t - 0.00004
    tuck = cuboid('Заправляемый клапан • без клеевых язычков',
                  (-half + 0.0007, half - tuck_depth, tuck_z - t),
                  (half - 0.0007, half - t, tuck_z), packaging)
    # Синяя печатная сторона клапана обращена вверх и видна через выемку.
    finish_surface(tuck, materials['tuck'], paper, (0, 0, 1),
                   lambda p: ((half - p.x) / span, (half - p.y) / tuck_depth), 0.025)

    backdrop = paper_material('Студия • тёплый матовый фон', color='#EAE6DF', gloss=False)
    floor = cuboid('Студийный фон', (-1, -1, -0.002), (1, 1, -0.00015), studio)
    floor.data.materials.append(backdrop)
    world = bpy.data.worlds.new('TIPO SVG • нейтральное окружение')
    world.use_nodes = True
    world.node_tree.nodes['Background'].inputs['Color'].default_value = (1, 1, 1, 1)
    world.node_tree.nodes['Background'].inputs['Strength'].default_value = 0.22
    scene.world = world
    area_light(studio, 'Ключевой софтбокс', (-0.09, -0.08, 0.18), (0, 0, 0.015), 0.12, 0.14)
    area_light(studio, 'Мягкое заполнение', (0.12, -0.015, 0.10), (0, 0, 0.015), 0.045, 0.11)
    area_light(studio, 'Узкий блик на ламинации', (-0.02, 0.11, 0.15),
               (0, 0, 0.02), 0.09, 0.13, 0.035)
    camera_data = bpy.data.cameras.new('TIPO SVG • предметная камера')
    camera = bpy.data.objects.new('Камера • лицевая сторона', camera_data)
    studio.objects.link(camera)
    camera.location = (0.095, -0.115, 0.205)
    point_at(camera, (0, 0, 0.012))
    camera_data.type = 'ORTHO'
    camera_data.ortho_scale = 0.120
    camera_data.clip_start = 0.001
    camera_data.clip_end = 20
    # Второй ракурс специально показывает крышку с логотипом и синюю выемку.
    lid_camera_data = bpy.data.cameras.new('TIPO SVG • контроль верхней крышки')
    lid_camera = bpy.data.objects.new('Камера • верхняя крышка и синий клапан', lid_camera_data)
    studio.objects.link(lid_camera)
    lid_camera.location = (0.055, 0.15, 0.095)
    point_at(lid_camera, (0, 0.006, 0.014))
    lid_camera.rotation_euler.rotate_axis('Z', math.pi)
    lid_camera_data.type = 'ORTHO'
    lid_camera_data.ortho_scale = 0.110
    lid_camera_data.clip_start = 0.001
    lid_camera_data.clip_end = 20
    scene['Исправление крышки'] = 'Один полный логотип из SVG; без повторяющегося узора.'
    scene['Синий клапан'] = '#2164FF на верхней стороне, видимой через полукруглую выемку.'
    scene.camera = camera
    scene.render.engine = 'CYCLES'
    scene.cycles.device = 'CPU'
    scene.cycles.samples = SAMPLES
    try:
        import _cycles
        scene.cycles.use_denoising = bool(getattr(_cycles, 'with_openimagedenoise', False))
    except ImportError:
        scene.cycles.use_denoising = False
    scene.cycles.use_adaptive_sampling = True
    scene.cycles.adaptive_threshold = 0.015
    scene.cycles.max_bounces = 10
    scene.cycles.seed = 612
    scene.render.resolution_x = RENDER_SIZE
    scene.render.resolution_y = RENDER_SIZE
    scene.render.resolution_percentage = 100
    scene.render.image_settings.file_format = 'PNG'
    scene.render.image_settings.color_mode = 'RGBA'
    scene.render.image_settings.color_depth = '8'
    scene.render.film_transparent = False
    scene.view_settings.view_transform = 'Standard'
    scene.view_settings.look = 'None'
    scene.view_settings.exposure = 0
    scene.view_settings.gamma = 1
    upright_view = create_upright_view(scene)
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    blend_path = OUTPUT_DIR / ('TIPO_empty_SVG_' + stamp + '.blend')
    render_path = OUTPUT_DIR / ('TIPO_empty_SVG_' + stamp + '.png')
    scene.render.filepath = str(render_path)
    upright_view.render.filepath = str(OUTPUT_DIR / ('TIPO_top_' + stamp + '.png'))
    for screen in bpy.data.screens:
        for area in screen.areas:
            if area.type == 'VIEW_3D':
                area.spaces.active.clip_start = 0.001
                area.spaces.active.clip_end = 20
                area.spaces.active.region_3d.view_perspective = 'CAMERA'
                area.spaces.active.overlay.show_overlays = False
                area.spaces.active.shading.type = 'MATERIAL'
    bpy.ops.wm.save_as_mainfile(filepath=str(blend_path))
    print('TIPO SVG: сохранён BLEND: ' + str(blend_path), flush=True)
    print('TIPO SVG: карт внутри нет; вся графика упакована, окно геометрическое.', flush=True)
    if RENDER_NOW:
        bpy.ops.render.render(write_still=True, scene=scene.name)
        print('TIPO SVG: сохранён PNG: ' + str(render_path), flush=True)
    return scene


